def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    if n < 10:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'

    opp_c = sum(1 for my, opp in history if opp == 'C')
    my_c = sum(1 for my, opp in history if my == 'C')
    opp_d = n - opp_c
    my_d = n - my_c

    recent = history[-10:]
    recent_opp_c = sum(1 for my, opp in recent if opp == 'C')
    recent_opp_d = 10 - recent_opp_c

    recent20 = history[-20:]
    recent20_c = sum(1 for my, opp in recent20 if opp == 'C')

    forg = 0
    pun = 0
    start = n - 30
    if start < 1:
        start = 1

    for i in range(start, n):
        prev_my = history[i - 1][0]
        opp_now = history[i][1]
        if prev_my == 'D':
            if opp_now == 'C':
                forg += 1
            else:
                pun += 1

    nice = opp_c * 5 > n * 3
    very_nice = opp_c * 10 >= n * 7
    recent_nice = recent_opp_c >= 8
    very_recent_nice = recent_opp_c >= 9
    hostile = (opp_c * 10 <= n * 3) or (recent_opp_c <= 2)
    forgiving = (forg > 0 and forg >= pun) or (my_d > 0 and opp_d == 0)

    if hostile:
        return 'D'

    if recent_opp_d >= 7:
        return 'D'

    if not nice and recent_opp_c <= 6:
        return 'D'

    if n >= 20:
        d_after_d = sum(
            1 for i in range(1, len(recent20))
            if recent20[i - 1][1] == 'D' and recent20[i][1] == 'D'
        )
        if d_after_d >= 5:
            return 'D'

    if opp_d == 0:
        if my_d == 1 and my_last == 'D':
            return 'C'

        if my_d > 0 and very_recent_nice:
            return 'D'

        if my_d == 0 and n >= 95:
            return 'D'

        if n >= 40 and rng.random() < 0.03:
            return 'D'

        if n >= 70 and rng.random() < 0.07:
            return 'D'

        return 'C'

    if opp_last == 'C':
        if my_last == 'D' and forgiving and very_nice and recent_nice:
            return 'D'

        if forgiving and very_nice and very_recent_nice and my_d > 0:
            return 'D'

        if n >= 80 and forgiving and very_nice and recent_nice:
            return 'D'

        if n >= 92 and forgiving and nice and recent_opp_c >= 7:
            return 'D'

        return 'C'

    if very_recent_nice and nice:
        return 'C'

    if my_last == 'D' and recent_opp_c >= 7 and very_nice and rng.random() < 0.30:
        return 'C'

    if nice and recent20_c >= 12 and recent_opp_d <= 3:
        return 'C'

    return 'D'
